INSERT INTO interpretation_templates (condition_key, condition_value, category, title, summary, content, weight, is_active) VALUES
('day_pillar', '갑자', 'general', '갑자일주 · 총운', '겨울의 큰 나무처럼 차분하면서도 속으로 생명력을 품고 있는 기질입니다.', '갑목의 뻗어나가려는 기상과 자수의 지혜롭고 차분한 성향이 결합된 형태입니다. 수생목의 구조로, 탐구심과 학구열이 높으며 겉으로는 조용하고 다정해 보이지만 내면에는 강한 고집과 굽히지 않는 자존심이 자리 잡고 있습니다. 감수성이 풍부하고 타인의 시선을 의식하는 면도 다분한 편입니다.', 70, true),
('day_pillar', '갑자', 'career', '갑자일주 · 직업', '지식과 자격을 활용하는 교육, 연구, 기획 분야에 적합한 기질입니다.', '몸을 쓰는 일보다는 머리를 쓰는 직무에 유리하며 교육자, 학자, 연구원, 작가 등 전문적인 지식을 요구하는 분야에서 능력을 발휘하기 좋습니다. 새로운 것을 창조하고 기획하는 역할에 잘 맞지만, 끈기 있게 마무리하는 뒷심을 보완하는 것이 중요합니다.', 70, true),
('day_pillar', '갑자', 'love', '갑자일주 · 연애', '다정하고 배려심이 깊지만, 때로는 속마음을 숨겨 오해를 살 수 있습니다.', '타인에게 호감을 주는 매력을 지니고 있으며 상대방을 세심하게 챙기고 따뜻하게 대하는 성향이 강합니다. 그러나 속마음을 쉽게 드러내지 않고 혼자 고민을 안고 가는 편이라 상대방이 답답함을 느낄 수도 있으므로, 솔직하게 소통하려는 태도가 관계에 도움이 됩니다.', 70, true),
('day_pillar', '갑자', 'wealth', '갑자일주 · 재물', '안정적인 지식 재산권이나 문서 형태의 자산을 통해 부를 축적하는 성향입니다.', '위험 부담이 큰 투자보다는 안전하게 자산을 늘려가는 방식을 선호합니다. 부동산 문서나 자격증, 학위 등 무형의 가치나 지식 기반의 자산이 재물로 이어지는 구조를 지닙니다. 전문성을 꾸준히 키워나가는 과정에서 자연스럽게 경제적 안정이 뒤따르는 흐름을 가집니다.', 70, true),
('day_pillar', '갑자', 'health', '갑자일주 · 건강', '차갑고 습한 기운이 강하므로 몸을 따뜻하게 유지하는 데 신경 쓰면 좋습니다.', '수 기운에 의해 몸이 차가워질 수 있는 특성이 있으므로 평소 아랫배를 따뜻하게 하고 혈액순환에 신경을 쓰는 것이 좋습니다. 신경성 스트레스나 위장 장애에 노출되기 쉬우니 규칙적인 식습관과 가벼운 운동으로 심신의 안정을 취하는 것이 이롭습니다.', 70, true),
('day_pillar', '을축', 'general', '을축일주 · 총운', '언 땅에 뿌리를 내린 잡초처럼 강인한 생명력과 인내심을 지닌 기질입니다.', '을목의 유연함과 축토의 묵묵한 인내심이 어우러져 척박한 환경에서도 끈질기게 버티는 특성을 가집니다. 겉으로는 부드럽고 타협적으로 보이지만, 속에는 강한 집념과 굽히지 않는 오기가 숨어 있습니다. 묵묵히 자신의 뜻을 관철해 나가는 대기만성형의 성향이 두드러집니다.', 70, true),
('day_pillar', '을축', 'career', '을축일주 · 직업', '치밀함과 끈기를 요구하는 재무, 부동산, 연구 및 종교 분야에 잘 맞습니다.', '흙을 파고 인내하는 성향과 저장하려는 습성이 있어 꼼꼼함을 요하는 재무나 회계, 금융 분야에 재능을 보입니다. 또한 부동산 관련 직업이나 한 분야를 깊게 파고드는 연구직, 특수한 기술직에서도 끈기 있게 성과를 쌓아올리는 데 유리합니다.', 70, true),
('day_pillar', '을축', 'love', '을축일주 · 연애', '현실적이고 신중한 태도로 인연을 맺으며, 책임감 있는 연애를 추구합니다.', '쉽게 마음을 열지 않고 상대를 꼼꼼히 살피는 신중함이 있어 화려함보다는 안정적이고 실질적인 관계를 선호합니다. 한 번 맺은 인연에 대해서는 끝까지 책임을 다하려는 의리가 강하지만, 지나치게 현실적인 면이 부각되면 다소 무뚝뚝하게 비칠 수 있습니다.', 70, true),
('day_pillar', '을축', 'wealth', '을축일주 · 재물', '근검절약과 저축을 바탕으로 알뜰하게 자산을 모으는 알부자 성향입니다.', '재물을 허투루 쓰지 않고 꼼꼼하게 관리하는 능력이 탁월해 겉으로 드러나지 않게 상당한 부를 축적하는 경우가 많습니다. 투기적인 이익보다는 안정적인 자산에 투자하여 차곡차곡 불려 나가는 방식이 유리하며, 금전 거래에 있어 매우 신중한 태도를 취합니다.', 70, true),
('day_pillar', '을축', 'health', '을축일주 · 건강', '간 기능이나 비위장의 건강에 유의하고 몸을 따뜻하게 보호하면 좋습니다.', '겨울의 흙에 뿌리를 내린 형상이므로 몸이 냉해지기 쉬운 체질을 가집니다. 소화기 계통의 건강을 꾸준히 관리하고 스트레스를 속으로 삭여 간에 무리가 가지 않도록 주의해야 합니다. 적절한 휴식과 스트레스 발산이 건강 유지에 큰 도움이 됩니다.', 70, true),
('day_pillar', '병인', 'general', '병인일주 · 총운', '떠오르는 태양처럼 밝고 명랑하며, 추진력과 호기심이 넘치는 기질입니다.', '병화의 열정적이고 환한 빛이 인목의 생동감 넘치는 기운을 받아 맹렬하게 타오르는 형상입니다. 끊임없이 아이디어가 샘솟고 새로운 일에 도전하는 것을 즐기며, 다재다능하고 낙천적인 면모를 보입니다. 불의를 참지 못하는 정의감이 강하고 자기 표현이 확실한 편입니다.', 70, true),
('day_pillar', '병인', 'career', '병인일주 · 직업', '창의력과 표현력을 발휘할 수 있는 교육, 언론, 방송, 기획 분야에 적합합니다.', '활동적이고 기발한 사고력을 바탕으로 가만히 앉아 있는 일보다는 움직이며 창조적인 결과를 내는 업무에 유리합니다. 가르치는 직무나 언론인, 예술가, 디자이너 등 사람들의 시선을 끌고 영감을 주는 역할에서 리더십을 발휘하기 좋습니다.', 70, true),
('day_pillar', '병인', 'love', '병인일주 · 연애', '적극적이고 화끈한 애정 표현을 즐기며 낭만적인 분위기를 잘 타는 성향입니다.', '마음에 드는 상대에게 주저 없이 다가가는 열정을 지녔으며, 감정 표현이 풍부하여 관계를 주도적으로 이끌어갑니다. 하지만 쉽게 타오르는 만큼 감정의 기복에 따라 흥미를 잃을 수도 있으니, 인내심을 갖고 상대와의 다름을 인정하며 맞춰가는 노력이 필요합니다.', 70, true),
('day_pillar', '병인', 'wealth', '병인일주 · 재물', '명예와 성취를 추구하는 과정에서 자연스럽게 재물이 따라오는 흐름을 가집니다.', '재물 자체를 좇기보다는 자신의 이상이나 프로젝트의 성공을 중시하는 경향이 짙습니다. 빠른 두뇌 회전과 풍부한 아이디어를 활용해 큰 수익을 창출해 내지만, 충동적인 지출이나 과감한 투자로 재물이 흩어지기 쉬우므로 계획적인 금전 관리가 요구됩니다.', 70, true),
('day_pillar', '병인', 'health', '병인일주 · 건강', '에너지 소모가 큰 편이므로 심혈관계 및 신경계 건강에 신경 쓰면 좋습니다.', '활동량이 많고 성격이 급해 쉽게 피로가 누적되거나 신경이 날카로워질 수 있습니다. 심장이나 신경 계통에 무리가 오지 않도록 충분한 수면을 취하고 마음의 화를 다스리는 명상이나 휴식을 일상화하여 신체의 리듬을 안정시키는 것이 중요합니다.', 70, true),
('day_pillar', '정묘', 'general', '정묘일주 · 총운', '어둠 속 촛불처럼 따뜻하면서도 섬세하고 예민한 감수성을 지닌 기질입니다.', '정화의 은은한 온기와 묘목의 여린 기운이 만나, 직관력이 뛰어나고 예술적 감각이 발달한 특성을 가집니다. 겉으로는 조용하고 남을 배려하는 친절함이 돋보이지만, 내면에는 생각이 많고 다소 예민한 면이 존재합니다. 주변 분위기를 부드럽게 만드는 섬세한 매력이 특징입니다.', 70, true),
('day_pillar', '정묘', 'career', '정묘일주 · 직업', '섬세함과 직관력을 요하는 예술, 디자인, 상담 및 정신적인 분야에 적합합니다.', '타인의 마음을 헤아리는 공감 능력과 미적 감각이 뛰어나 디자인, 미용, 예술 분야 등에서 두각을 나타냅니다. 또한 사람들의 상처를 보듬는 상담사나 정신적인 가치를 다루는 일에서 능률을 올리며, 독립적으로 기술을 발휘할 때 만족감이 높습니다.', 70, true),
('day_pillar', '정묘', 'love', '정묘일주 · 연애', '낭만적이고 부드러운 관계를 지향하며 상대의 세심한 배려에 크게 감동합니다.', '다정다감하고 연인에게 헌신적인 태도를 보이지만 마음이 여려 상처를 쉽게 받는 편입니다. 거친 방식보다는 자신의 섬세한 감정을 알아주고 따뜻하게 감싸주는 사람에게 안정감을 느끼며, 감정 기복이 있을 때 깊은 대화로 소통하는 것이 바람직합니다.', 70, true),
('day_pillar', '정묘', 'wealth', '정묘일주 · 재물', '전문적인 기술이나 뛰어난 감각을 통해 꾸준하게 재물을 모아가는 성향입니다.', '대담한 승부수를 띄우기보다는 자신만의 특출난 재능과 아이디어를 바탕으로 안정적인 수익을 올리는 구조에 강합니다. 타인의 말에 흔들려 무리하게 투자하는 것을 피하고 문서나 자격증 등을 통해 경제적 기반을 다지는 것이 안전하고 유리합니다.', 70, true),
('day_pillar', '정묘', 'health', '정묘일주 · 건강', '신경이 예민해지기 쉬우니 시력 보호와 정신적 안정에 유의하면 좋습니다.', '생각이 많아 불면증이나 편두통 등 신경성 질환을 겪을 수 있으므로 스트레스를 건전하게 풀어내는 것이 중요합니다. 시력이 약해질 우려가 있으니 눈의 피로를 자주 풀어주고, 다도나 가벼운 산책 등 정서적 안정을 돕는 정적인 활동을 권장합니다.', 70, true),
('day_pillar', '무진', 'general', '무진일주 · 총운', '거대한 산맥처럼 듬직하고 스케일이 크며, 포용력과 뚝심이 돋보이는 기질입니다.', '무토의 중후함과 진토의 다양성이 결합되어 거대한 대지에 만물을 품는 듯한 독립심과 주관을 가집니다. 어떤 어려움에도 쉽게 흔들리지 않는 강한 인내력을 지니고 있으며, 무뚝뚝해 보일 수 있으나 속은 든든하고 신의를 중시하며 배포가 큰 성향을 보입니다.', 70, true),
('day_pillar', '무진', 'career', '무진일주 · 직업', '독립적이고 스케일이 큰 건축, 부동산, 군검경 또는 리더십을 요하는 분야에 맞습니다.', '지시를 받기보다는 스스로 주도권을 쥐고 일할 때 능력을 한껏 발휘합니다. 생사여탈을 다루는 직종이나 거대한 재물을 다루는 건축, 토목, 정치 분야 등 굵직한 업무에서 두각을 나타내며 특유의 추진력으로 프로젝트를 이끌어가는 힘이 있습니다.', 70, true),
('day_pillar', '무진', 'love', '무진일주 · 연애', '신중하게 인연을 맺으며, 한 번 맺은 관계는 든든하게 책임지려는 태도를 보입니다.', '표현이 다소 서툴러 로맨틱한 면은 부족할 수 있지만 가벼운 만남을 꺼리고 진중하게 상대를 대합니다. 위기 상황에서 배우자나 연인을 끝까지 지켜내는 책임감이 탁월하나, 주장이 강해 마찰이 생길 수 있으니 상대의 의견에 부드럽게 귀 기울이는 양보가 필요합니다.', 70, true),
('day_pillar', '무진', 'wealth', '무진일주 · 재물', '크게 잃고 크게 버는 기복이 있으나 결국 큰 자산을 굴리는 대부호의 기질입니다.', '작은 돈에 연연하지 않고 굵직한 투자나 큰 사업에 뛰어드는 배포를 지녀 잠재적인 재물복이 두텁습니다. 그러나 승부욕에 이끌려 무리한 확장을 시도하다 손실을 볼 수도 있으므로, 부동산과 같은 묵직하고 안정적인 자산에 묻어두는 방식이 재산을 지키는 데 매우 유리합니다.', 70, true),
('day_pillar', '무진', 'health', '무진일주 · 건강', '위장 등 소화기 계통의 건강 관리에 신경 쓰고 체중 조절에 유의하면 좋습니다.', '흙의 기운이 뭉쳐 소화 불량이나 위장 질환 등에 노출되기 쉬운 체질이므로 규칙적인 식습관이 중요합니다. 스트레스를 고집스럽게 안고 가면 소화기에 무리가 올 수 있으므로, 땀을 내는 운동이나 야외 활동으로 기운을 순환시키는 것이 건강 유지에 바람직합니다.', 70, true),
('day_pillar', '기사', 'general', '기사일주 · 총운', '따뜻한 대지처럼 사람을 품는 다정함 속에 치밀하고 날카로운 통찰력을 숨긴 기질입니다.', '기토의 포용력과 사화의 밝고 뜨거운 기운이 만나 겉으로는 부드럽고 수더분해 보이지만 내면에는 강한 주관과 뛰어난 분석력을 갖춘 성향입니다. 다재다능하고 두뇌 회전이 빠르며 환경 변화에 민첩하게 적응하는 유연성과 추진력을 동시에 발휘합니다.', 70, true),
('day_pillar', '기사', 'career', '기사일주 · 직업', '전문적인 지식과 언변을 활용하는 교육, 상담, 기획, 정보통신 분야에 적합합니다.', '상황 판단이 빠르고 타인을 가르치거나 설득하는 능력이 뛰어나 교육자, 언론인, 상담사로 활동하기 좋습니다. 꼼꼼한 정보 처리 능력으로 IT 분야나 기획 업무에서도 좋은 성과를 내며, 한 곳에 머물기보다 활동적인 환경에서 역량이 돋보입니다.', 70, true),
('day_pillar', '기사', 'love', '기사일주 · 연애', '다정하고 헌신적으로 상대를 대하지만, 마음속 잣대로 꼼꼼히 평가하는 신중함이 있습니다.', '따뜻한 성품으로 연인을 세심하게 챙기며 안정적인 관계를 추구하지만, 감정 이면에 논리적이고 냉정한 판단력이 있어 상대를 예리하게 살피는 경향이 있습니다. 지나친 간섭이나 의심으로 이어지지 않도록 상호 신뢰를 바탕으로 솔직하게 대화하는 것이 좋습니다.', 70, true),
('day_pillar', '기사', 'wealth', '기사일주 · 재물', '지식과 정보를 활용하여 착실하게 문서를 통해 부를 쌓아가는 안정적인 흐름입니다.', '치밀한 계획 하에 자산을 운용하며, 실속을 중시하여 불필요한 지출을 삼가는 성향이 강합니다. 부동산 문서나 저작권, 자격증 등 무형의 전문 지식이 실질적인 재물로 연결되는 구조이므로, 자신의 분야에서 전문성을 굳건히 다지는 것이 경제적 풍요를 가져옵니다.', 70, true),
('day_pillar', '기사', 'health', '기사일주 · 건강', '열기가 속으로 뭉치기 쉬우므로 심혈관 및 호흡기 질환 관리에 신경 쓰면 좋습니다.', '생각이 많고 스트레스를 내면으로 삭이는 편이라 화기가 정체되어 혈압이나 심장 건강에 무리가 올 수 있습니다. 시원하고 맑은 공기를 쐬거나 가벼운 등산 등을 통해 가슴의 답답함을 풀어주고 심신의 긴장을 이완시키는 습관이 필요합니다.', 70, true),
('day_pillar', '경오', 'general', '경오일주 · 총운', '제련된 강철처럼 반듯하고 절도가 있으며, 명예와 원칙을 중시하는 깔끔한 기질입니다.', '경금의 단단함과 오화의 뜨거운 열기가 결합하여 불 속에서 단련되는 금속의 형상을 띱니다. 원리원칙을 중요하게 생각하고 불의와 타협하지 않는 곧은 성정을 지녔으며, 예의 바르고 단정하여 조직 내에서 반듯한 인물로 인정받는 경우가 많습니다.', 70, true),
('day_pillar', '경오', 'career', '경오일주 · 직업', '규칙과 체계가 뚜렷한 공직, 법률, 군검경, 대기업 조직 생활에 매우 잘 맞습니다.', '책임감이 투철하고 도덕성을 중시하므로 법조인, 공무원, 군인, 경찰 등 공적인 업무에서 탁월한 역량을 발휘합니다. 위계질서가 명확한 조직에서 관리자나 리더의 역할로 승진하기에 유리하며, 명예를 바탕으로 한 직업에서 큰 성취를 이룹니다.', 70, true),
('day_pillar', '경오', 'love', '경오일주 · 연애', '매너 있고 세련된 태도로 호감을 사며, 정도를 걷는 깔끔한 연애를 지향합니다.', '단정하고 매력적인 외모나 분위기로 이성의 시선을 끌며, 예의를 갖춰 상대를 대합니다. 하지만 자존심이 강하고 옳고 그름을 따지는 성향 때문에 감정적인 마찰이 생겼을 때 다소 냉정하게 돌아설 수 있으므로, 서로의 결점을 포용하는 유연함이 필요합니다.', 70, true),
('day_pillar', '경오', 'wealth', '경오일주 · 재물', '투기보다는 직장에서의 안정적인 지위와 명예를 통해 재물을 얻는 꼿꼿한 성향입니다.', '돈을 위해 원칙을 꺾기보다는 체면과 명예를 중시하므로, 큰 한탕주의보다는 착실한 저축이나 월급 명목의 안정적 수입을 통해 자산을 불려 나갑니다. 무리한 사업 투자보다는 직위가 올라감에 따라 자연스레 경제적 보상이 따르는 구조에 적합합니다.', 70, true),
('day_pillar', '경오', 'health', '경오일주 · 건강', '금기운이 화기운에 자극받으므로 폐나 호흡기, 장 건강에 신경 쓰면 좋습니다.', '규칙적인 생활을 하는 편이지만 화기가 금기를 극하는 구조상 폐나 대장 기능이 예민해질 수 있습니다. 건조함을 피하고 수분을 충분히 섭취하며, 땀을 적당히 배출하는 유산소 운동으로 심폐 기능을 강화하여 스트레스를 조절하는 것이 이롭습니다.', 70, true),
('day_pillar', '신미', 'general', '신미일주 · 총운', '섬세한 보석처럼 예리하고 세련된 감각을 지녔으나 내면의 고집이 대단히 강한 기질입니다.', '신금의 날카롭고 완성된 기운이 미토의 건조하고 뜨거운 흙과 만나, 겉으로는 차분하고 이지적이나 속으로는 굽히지 않는 날카로운 집념을 가집니다. 통찰력과 직관이 뛰어나 만물을 꿰뚫어 보는 안목이 있으며, 자신이 세운 기준과 원칙을 철저히 지키려는 완벽주의 성향이 다분합니다.', 70, true),
('day_pillar', '신미', 'career', '신미일주 · 직업', '정밀함과 특수성을 요구하는 의료, 금융, 전문 기술직, 기획 분야에 적합합니다.', '세밀한 부분까지 놓치지 않는 예리함이 있어 의사, 한의사, 세무사 등 전문 면허를 요구하는 직종이나 첨단 기술직에서 두각을 나타냅니다. 또한 비판적 사고가 발달해 기획이나 감찰 업무 등 오류를 잡아내고 바로잡는 역할에서 능률을 발휘하기 좋습니다.', 70, true),
('day_pillar', '신미', 'love', '신미일주 · 연애', '신중하고 까다로운 편이라 마음을 열기 어렵지만, 한 번 정을 주면 깊이 헌신합니다.', '상대방의 조건과 성향을 예리하게 분석하므로 쉽게 연애에 빠지지 않는 편입니다. 본인의 높은 기준을 충족시키는 사람에게는 헌신적인 사랑을 쏟지만, 상대의 단점을 발견하면 가차 없이 비판하는 차가운 면이 있어 부드럽게 감싸주는 포용력이 관계 유지를 위해 꼭 필요합니다.', 70, true),
('day_pillar', '신미', 'wealth', '신미일주 · 재물', '치밀한 계산과 분석을 바탕으로 재물을 안정적이고 철저하게 관리하는 성향입니다.', '돈의 흐름을 짚어내는 감각이 뛰어나며 허튼 데 돈을 쓰지 않는 절약 정신이 강합니다. 건조한 흙 속에 재물을 저장하는 형상으로 큰 기복 없이 부동산이나 전문 자격을 통해 재산을 축적하는 데 유리하며, 동업보다는 독자적으로 자산을 운용하는 것이 바람직합니다.', 70, true),
('day_pillar', '신미', 'health', '신미일주 · 건강', '건조하고 날카로운 기운이 강하므로 호흡기 계통과 관절 건강에 유의하면 좋습니다.', '수기가 부족해지기 쉬운 구조이므로 몸이 건조해지기 쉽고 폐나 기관지가 약해질 수 있습니다. 평소 수분을 충분히 섭취하고 피부 보습에 신경 쓰며, 뼈나 관절에 무리가 가지 않도록 스트레칭이나 요가 등으로 유연성을 기르는 것이 건강에 긍정적입니다.', 70, true),
('day_pillar', '임신', 'general', '임신일주 · 총운', '거대한 강물이 바위에서 솟아나듯 두뇌가 총명하고 거침없이 흘러가는 기질입니다.', '임수의 넓고 유연한 포용력과 신금의 단단하고 날카로운 기운이 만나 큰 물줄기를 이루는 형상입니다. 암기력과 두뇌 회전이 비상하며 새로운 지식을 습득하고 응용하는 능력이 탁월합니다. 어떠한 환경에도 유연하게 적응하지만 한 번 결심하면 거침없이 밀고 나가는 돌파력을 지녔습니다.', 70, true),
('day_pillar', '임신', 'career', '임신일주 · 직업', '지식과 아이디어를 널리 펼치는 교육, 무역, 외교, IT 및 유통 분야에 잘 맞습니다.', '금생수의 강한 흐름을 타므로 한곳에 정체되기보다는 활발히 교류하고 이동하는 업무에 적합합니다. 학자나 교육자로서 깊은 지식을 전달하거나 외국어와 글로벌 감각을 살려 무역, 외교, 해운업 분야에서 큰 무대를 배경으로 역량을 펼칠 때 성취가 큽니다.', 70, true),
('day_pillar', '임신', 'love', '임신일주 · 연애', '자유롭고 호탕한 성향으로 매력이 넘치나, 얽매이는 것을 싫어하는 자유로운 영혼입니다.', '사람을 끌어당기는 특유의 언변과 매력으로 이성에게 인기가 많으며 연애를 주도하는 편입니다. 그러나 한 사람에게 깊이 정착하기보다 다소 구속받기 싫어하는 면이 있어 상대를 불안하게 할 수 있으므로, 책임감 있고 진지하게 관계에 임하는 태도가 뒷받침되어야 합니다.', 70, true),
('day_pillar', '임신', 'wealth', '임신일주 · 재물', '아이디어와 정보력을 활용하여 유동적인 자산과 사업을 통해 재물을 창출하는 성향입니다.', '돈이 한곳에 묶여 있는 것보다 끊임없이 회전하고 융통될 때 부가 커지는 흐름을 가집니다. 탁월한 정보력과 직관력을 바탕으로 유통이나 무역, 투자 등 흐름을 타는 분야에서 수익을 내기에 좋으나, 돈이 쉽게 빠져나갈 수 있으므로 문서화하여 묶어두는 지혜가 필요합니다.', 70, true),
('day_pillar', '임신', 'health', '임신일주 · 건강', '물이 차가워지기 쉬우므로 하복부를 따뜻하게 하고 신장 및 방광 건강에 신경 쓰면 좋습니다.', '신체의 수분 대사가 활발한 편이나 금수 기운이 강해져 몸이 찰 수 있으니 보온에 주의해야 합니다. 생식기나 비뇨기 계통의 건강을 꾸준히 체크하고, 가벼운 땀을 내어 몸의 냉기를 몰아내는 활동적인 운동을 규칙적으로 하는 것이 도움이 됩니다.', 70, true),
('day_pillar', '계유', 'general', '계유일주 · 총운', '맑은 옹달샘에 비친 달처럼 맑고 순수하며, 뛰어난 직관과 기억력을 지닌 기질입니다.', '계수의 부드럽고 섬세한 기운이 유금의 깨끗하고 날카로운 금속을 만나 오염을 싫어하고 청결함을 추구하는 성향을 띱니다. 지적 호기심이 강하고 암기력과 계산 능력이 매우 뛰어나며, 겉보기에는 여리고 다정하지만 속은 얼음처럼 차갑고 맺고 끊음이 확실한 외유내강형입니다.', 70, true),
('day_pillar', '계유', 'career', '계유일주 · 직업', '정밀한 분석과 예리함을 요구하는 기획, 회계, IT, 전문 연구 분야에 훌륭하게 맞습니다.', '머리가 비상하고 정보를 체계화하는 능력이 탁월하여 데이터 분석, 프로그래밍, 회계사 등 정밀함을 요하는 직종에서 능률을 발휘합니다. 금생수의 맑은 기운으로 학문과 종교, 예술 분야에서도 직관력을 바탕으로 깊이 있는 성과를 이뤄냅니다.', 70, true),
('day_pillar', '계유', 'love', '계유일주 · 연애', '깨끗하고 세련된 관계를 원하며 상대의 작은 단점에도 민감하게 반응할 수 있습니다.', '이상형에 대한 기준이 확고하여 아무에게나 마음을 주지 않고 까다롭게 인연을 선택하는 편입니다. 한 번 마음을 열면 다정하게 대하지만 상대방의 사소한 실수나 불결한 모습을 보면 쉽게 마음이 식거나 날카로워질 수 있으므로, 너그러운 이해심을 발휘하는 것이 필요합니다.', 70, true),
('day_pillar', '계유', 'wealth', '계유일주 · 재물', '전문 지식과 자격증을 바탕으로 알뜰하게 관리하여 재물을 축적하는 성향입니다.', '무모한 모험을 즐기기보다는 철저한 계산과 계획 아래 안전하게 자산을 운용하는 방식을 선호합니다. 지식 재산권이나 전문적인 기술력을 바탕으로 한 수익 창출에 유리하며, 금전 관리가 매우 치밀하여 불필요한 낭비 없이 차곡차곡 재산을 모아가는 것에 능합니다.', 70, true),
('day_pillar', '계유', 'health', '계유일주 · 건강', '신경이 날카로워지기 쉬우므로 심리적 안정과 신장, 방광 건강 관리에 유의하면 좋습니다.', '스트레스에 예민하게 반응하여 편두통이나 불면증에 시달릴 수 있으니 마음을 편하게 갖는 연습이 필요합니다. 금수 기운이 강해 몸이 냉해지기 쉬우니 따뜻한 차나 반신욕을 즐기며 혈액 순환을 원활히 하고 비뇨기 계통을 보호하는 생활 습관을 권장합니다.', 70, true),
('day_pillar', '갑술', 'general', '갑술일주 · 총운', '가을 산의 우뚝 솟은 나무처럼 명예를 중시하고 독립심이 강한 기질입니다.', '갑목의 뻗어나가는 기상과 술토의 메마른 대지가 결합되어, 거친 환경에서도 굴하지 않고 주관을 관철하는 강인함을 지녔습니다. 속에는 화(火)의 기운을 품고 있어 겉으로는 다소 무뚝뚝해 보여도 내면은 다정하고 의리가 있으며, 자신이 옳다고 믿는 일에는 타협하지 않는 곧은 성품을 가집니다.', 70, true),
('day_pillar', '갑술', 'career', '갑술일주 · 직업', '리더십과 전문성을 발휘할 수 있는 군검경, 정치, 부동산, 교육 분야에 적합합니다.', '남의 밑에서 통제받는 것을 꺼리며 독립적인 영역을 개척하는 일에 탁월합니다. 명예와 권위를 중시하여 법조계나 활인업(상담, 종교) 등 타인에게 선한 영향력을 미치는 직업이나, 강한 추진력을 요하는 부동산 개발, 토목 등 스케일이 큰 업무에서 능력을 발휘합니다.', 70, true),
('day_pillar', '갑술', 'love', '갑술일주 · 연애', '책임감이 강하고 한 번 맺은 인연에 헌신하지만, 자기주장이 다소 강한 편입니다.', '연애에 있어서 가벼운 만남보다는 신뢰를 바탕으로 한 진지한 관계를 지향합니다. 내 사람이라고 생각하면 아낌없이 챙기고 보호하려 하지만, 무뚝뚝한 표현 방식과 꺾이지 않는 자존심 탓에 마찰이 생길 수 있으므로 부드럽게 감정을 표현하는 연습이 필요합니다.', 70, true),
('day_pillar', '갑술', 'wealth', '갑술일주 · 재물', '안정적인 문서 자산이나 부동산을 통해 묵직하게 부를 축적하는 흐름에 강합니다.', '재물 창고를 깔고 앉은 형상으로 잠재적인 재물운이 강력하며 한 번 재물을 거머쥐면 잘 놓치지 않습니다. 유행을 타는 투기성 사업보다는 흙과 관련된 부동산 투자나 자신의 확고한 전문 기술을 통해 안정적으로 자산을 지키고 불려 나가는 방식이 매우 유리합니다.', 70, true),
('day_pillar', '갑술', 'health', '갑술일주 · 건강', '건조하고 화기가 잠재되어 있으므로 간장 및 위장 건강에 유의하고 수분을 보충하면 좋습니다.', '수기가 부족해지기 쉬운 구조로 피로가 간에 누적되기 쉬우며 위장에 열이 찰 수 있습니다. 평소 물을 자주 마시고 충분한 휴식을 취하며, 무리한 활동보다는 명상이나 스트레칭을 통해 몸의 긴장을 풀어주고 간 기능을 보호하는 것이 바람직합니다.', 70, true),
('day_pillar', '을해', 'general', '을해일주 · 총운', '호수 위에 떠 있는 연꽃처럼 온화하고 영감과 직관력이 뛰어난 기질입니다.', '을목의 유연함과 해수의 포용력이 만나 부드럽고 다정다감한 성품을 지녔으며 환경 적응력이 매우 뛰어납니다. 겉모습은 평화롭고 친절하지만 내면에는 신비로운 영감과 비상한 두뇌를 감추고 있습니다. 물 위를 떠도는 부초처럼 이리저리 이동하거나 변화를 추구하는 역마의 성향도 다분합니다.', 70, true),
('day_pillar', '을해', 'career', '을해일주 · 직업', '지식과 아이디어를 기반으로 하는 교육, 연구, 예술, 무역 분야에 훌륭하게 맞습니다.', '수생목의 인성 기운이 강하여 학문적 탐구심이 높고 통찰력이 예리하므로 학자, 교육자, 종교인으로 활동하기 좋습니다. 또한 활동적이고 이동을 즐기는 특성을 살려 해외 관련 무역업이나 유통, 창의력을 발휘하는 예술적 직무에서도 크게 성공할 잠재력이 있습니다.', 70, true),
('day_pillar', '을해', 'love', '을해일주 · 연애', '다정하고 로맨틱하게 상대에게 헌신하지만, 마음이 여려 상처에 민감한 편입니다.', '연인을 세심하게 배려하고 따뜻한 정을 나누는 것을 좋아하여 연애의 분위기를 잘 리드합니다. 그러나 상상력이 풍부하고 감정이 섬세하여 사소한 말 한마디에도 쉽게 상처받을 수 있으니, 상호 간의 깊은 신뢰와 안정감을 주는 대화가 관계 유지에 필수적입니다.', 70, true),
('day_pillar', '을해', 'wealth', '을해일주 · 재물', '자격증이나 학위, 문서를 바탕으로 지식 기반의 안정적인 재물을 창출하는 성향입니다.', '직접적인 상업이나 투기성 투자보다는 자신의 전문 지식이나 교육적 가치를 활용해 수입을 얻는 방식이 안전합니다. 해외 경험이나 외국어 능력을 자산으로 승화시키면 경제적 보상이 따르며, 재물을 축적할 때는 눈에 보이는 현금보다는 문서나 부동산 형태로 묶어두는 것이 좋습니다.', 70, true),
('day_pillar', '을해', 'health', '을해일주 · 건강', '냉기가 스며들기 쉬우므로 하복부를 따뜻하게 하고 간과 신경계 건강에 유의하면 좋습니다.', '습하고 찬 기운이 강해져 몸이 차가워질 수 있으니 족욕이나 반신욕 등으로 체온을 높이는 습관을 기르면 이롭습니다. 활동성에 비해 뼈나 관절이 약해질 우려가 있으므로 규칙적인 스트레칭을 생활화하고 신경성 위장병에 노출되지 않도록 마음을 편안하게 가져야 합니다.', 70, true),
('day_pillar', '병자', 'general', '병자일주 · 총운', '한밤중을 비추는 달빛처럼 화려하면서도 단정하고 예의를 중시하는 기질입니다.', '병화의 뜨거운 열정과 자수의 차가운 지혜가 결합되어 수화기제를 이루는 형태입니다. 화려하고 밝은 겉모습 이면에 차분하고 냉철한 이성을 지니고 있어 감정 조절에 능합니다. 원리원칙과 체면을 중요하게 생각하며 타인에게 흠잡히지 않으려는 자기 관리가 철저한 성향을 보입니다.', 70, true),
('day_pillar', '병자', 'career', '병자일주 · 직업', '명예와 규칙이 분명한 공직, 대기업, 법조, 교육 및 관리직에 매우 적합합니다.', '정관의 바르고 투명한 기운이 강해 위계질서가 뚜렷하고 도덕성을 요구하는 공무원이나 조직 생활에서 능력을 크게 인정받습니다. 사람들을 통솔하는 리더십과 논리적인 언변을 겸비하여 관리자나 교육자로서 뛰어난 두각을 나타내며 체계적인 업무에 강점을 보입니다.', 70, true),
('day_pillar', '병자', 'love', '병자일주 · 연애', '매너 있고 단정한 태도로 다가가며, 감정에 휩쓸리지 않는 이성적인 연애를 지향합니다.', '세련된 외모나 깔끔한 분위기로 이성의 시선을 사로잡지만, 연애에 있어서도 선을 지키며 함부로 흐트러지는 모습을 보이지 않습니다. 안정적이고 예측 가능한 관계를 원하며 상대방의 도덕성이나 예의를 중요하게 평가하므로 서로 예의를 지키고 신뢰를 쌓는 것이 바람직합니다.', 70, true),
('day_pillar', '병자', 'wealth', '병자일주 · 재물', '안정적인 직장에서의 승진이나 명예를 바탕으로 착실하게 재물을 모으는 흐름입니다.', '일확천금을 노리는 투기적인 방식보다는 땀방울과 명예에 걸맞은 정당한 수입을 선호합니다. 직위가 올라갈수록 자연스럽게 경제적 안정이 뒤따르는 구조이므로, 조직 내에서 자신의 가치를 높이고 꾸준하게 저축하며 자산을 관리하는 것이 재물을 지키는 가장 유리한 방법입니다.', 70, true),
('day_pillar', '병자', 'health', '병자일주 · 건강', '수와 화의 대립으로 인해 심혈관계와 비뇨기 계통의 건강 관리에 신경 쓰면 좋습니다.', '겉으로는 에너지가 넘쳐 보이나 스트레스를 내면에서 통제하려다 심장이나 혈압에 무리가 갈 수 있습니다. 규칙적인 생활 리듬을 유지하고 수분 섭취에 유의하며, 긴장을 완화시킬 수 있는 명상이나 가벼운 유산소 운동을 꾸준히 실천하는 것이 장기적인 건강에 도움이 됩니다.', 70, true),
('day_pillar', '정축', 'general', '정축일주 · 총운', '얼어붙은 땅을 녹이는 화로처럼 따뜻한 헌신과 끈질긴 인내력을 지닌 기질입니다.', '정화의 은은한 온기와 축토의 차갑고 묵묵한 성질이 어우러져 희생정신과 강한 집념을 띱니다. 겉으로는 조용하고 수더분해 보이지만 목표한 바를 위해 묵묵히 밤을 새우며 몰두하는 집중력이 대단합니다. 화를 잘 내지 않지만 한 번 폭발하면 걷잡을 수 없는 고집을 보여주기도 합니다.', 70, true),
('day_pillar', '정축', 'career', '정축일주 · 직업', '봉사정신과 전문 기술을 요구하는 의료, 종교, 요식업 및 특수 기획 분야에 적합합니다.', '남을 먹이고 살리는 활인업의 성향이 짙어 의사, 간호사, 심리 상담사 등으로 활약할 때 심리적 만족감과 직업적 성과가 큽니다. 또한 요식업이나 꼼꼼한 세공 기술을 요하는 분야에서도 두각을 나타내며, 창의적인 아이디어를 조용히 구체화하는 능력이 탁월합니다.', 70, true),
('day_pillar', '정축', 'love', '정축일주 · 연애', '한 번 정을 주면 깊고 헌신적으로 사랑하나, 속마음을 잘 드러내지 않는 신중함이 있습니다.', '쉽게 연애를 시작하기보다 상대방을 오랜 시간 지켜본 뒤 마음을 여는 편입니다. 연인에게 모성애나 부성애처럼 따뜻한 배려를 베풀지만 혼자서 감정을 삭이는 습관 탓에 상대방이 거리감을 느낄 수 있으므로, 감정을 숨기지 않고 진솔하게 표현하려는 노력이 필요합니다.', 70, true),
('day_pillar', '정축', 'wealth', '정축일주 · 재물', '근검절약과 저축을 바탕으로 남몰래 실속 있게 재물을 쌓아가는 알부자의 성향입니다.', '돈을 허투루 쓰는 법이 없고 꼼꼼하게 장부를 관리하듯 재산을 모으는 데 탁월한 소질이 있습니다. 화려하게 겉으로 드러내기보다는 부동산이나 현금성 자산을 금고에 보관하듯 안전하게 늘려 나가는 방식에 능하며, 끈기 있게 경제적 독립을 이루어냅니다.', 70, true),
('day_pillar', '정축', 'health', '정축일주 · 건강', '위장 장애나 빈혈에 유의하고 몸을 항상 따뜻하게 보존하는 데 신경 쓰면 좋습니다.', '차가운 흙의 기운에 열기를 빼앗기기 쉬운 구조이므로 몸이 냉해지고 혈액순환이 원활하지 않을 수 있습니다. 소화기가 약해질 우려가 있으니 찬 음식을 피하고 몸을 따뜻하게 덥혀주는 식단이나 반신욕을 활용하여 체온을 높게 유지하는 것이 건강을 지키는 비결입니다.', 70, true),
('day_pillar', '무인', 'general', '무인일주 · 총운', '산중의 호랑이처럼 기백이 넘치고 리더십이 강하며 위엄을 갖춘 기질입니다.', '무토의 거대한 대지와 인목의 역동적인 기운이 만나 스케일이 크고 독립심이 대단히 강한 성향을 보입니다. 매사에 당당하고 추진력이 뛰어나며, 위기에 처해도 굴하지 않고 뚫고 나가는 강한 의지력을 지녔습니다. 타인의 간섭을 싫어하고 명예와 권위를 중요하게 생각합니다.', 70, true),
('day_pillar', '무인', 'career', '무인일주 · 직업', '권력을 쥐고 역동적으로 움직이는 군검경, 정치, 무역 및 대규모 사업 분야에 맞습니다.', '조직의 말단보다는 사람들을 호령하고 이끄는 관리자나 리더의 위치에서 재능을 펼치기에 매우 유리합니다. 명예를 중시하는 공직이나 해외를 넘나드는 역마의 기운을 살린 무역, 물류, 대형 건축 프로젝트 등 역동적이고 굵직한 업무에서 눈부신 성취를 거둘 수 있습니다.', 70, true),
('day_pillar', '무인', 'love', '무인일주 · 연애', '솔직하고 당당한 연애를 선호하며 상대방을 책임지고 지켜주려는 듬직함이 있습니다.', '마음에 드는 상대에게 주저 없이 직진하는 편이며 관계를 주도적으로 이끌어갑니다. 배우자나 연인에 대한 보호 본능이 강하지만, 자존심이 세고 굽히는 것을 싫어하여 다툼 시 크게 부딪힐 수 있으니 상대의 감정을 부드럽게 헤아리고 양보하는 유연한 태도가 필요합니다.', 70, true),
('day_pillar', '무인', 'wealth', '무인일주 · 재물', '안정적인 문서보다 큰 명예와 사업적 성취를 통해 거대한 부를 창출해 내는 흐름입니다.', '작은 돈에 얽매이기보다는 큰 무대에서 자신의 능력을 펼침으로써 자연스럽게 큰 재물을 거머쥐는 구조입니다. 편관의 기운을 활용하여 명예와 직위를 얻어 경제력을 확보하는 것이 좋으며, 지나친 사업 확장보다는 안정적인 조직이나 부동산을 기반으로 리스크를 줄이는 것이 현명합니다.', 70, true),
('day_pillar', '무인', 'health', '무인일주 · 건강', '스트레스로 인한 위장병이나 신경성 질환에 노출되지 않도록 마음의 여유를 가지면 좋습니다.', '목극토의 강한 대립으로 인해 신경이 예민해지고 소화기 기능이 억눌리기 쉬운 체질입니다. 과도한 승부욕이나 완벽주의를 내려놓고 자연 속에서 등산을 즐기거나 규칙적인 운동을 통해 뭉친 기운을 발산하며 심신의 안정을 도모하는 것이 건강 관리에 중요합니다.', 70, true),
('day_pillar', '기묘', 'general', '기묘일주 · 총운', '풀밭을 뛰어노는 토끼처럼 환경 적응력이 뛰어나고 눈치가 빠르며 예민한 기질입니다.', '기토의 유연한 대지와 묘목의 부드러우면서도 끈질긴 생명력이 만나 다정다감하고 사람들과 잘 어울리는 성향입니다. 겉으로는 부드럽고 타협적으로 보이지만, 편관의 영향으로 내면에는 긴장감과 예민함이 서려 있어 주변 상황이나 타인의 시선을 기민하게 파악하는 능력이 출중합니다.', 70, true),
('day_pillar', '기묘', 'career', '기묘일주 · 직업', '섬세하고 예리한 감각을 살리는 기획, 디자인, 교육, 활인(상담) 분야에 적합합니다.', '눈치가 빠르고 꼼꼼하여 사람들의 니즈를 파악하는 기획 업무나 미적 감각을 발휘하는 디자인, 예술 분야에서 역량을 뽐냅니다. 목극토의 긴장감을 전문성으로 승화시켜 남을 치료하고 상담해 주는 활인업이나 학생들을 통솔하는 교육 분야에서도 크게 성공할 수 있습니다.', 70, true),
('day_pillar', '기묘', 'love', '기묘일주 · 연애', '정 많고 다정하게 상대를 챙기나, 마음 한편에 불안감이나 의심을 품기 쉬운 편입니다.', '부드럽고 세심한 태도로 연인의 호감을 얻지만, 예민한 감수성 탓에 상대의 작은 행동에도 상처를 받거나 과도하게 신경을 곤두세울 수 있습니다. 서로에 대한 확고한 믿음을 심어주는 진정성 있는 대화가 중요하며, 상대를 편안하게 믿고 의지하려는 노력이 관계 유지에 도움이 됩니다.', 70, true),
('day_pillar', '기묘', 'wealth', '기묘일주 · 재물', '정밀한 기술이나 전문 지식을 바탕으로 차곡차곡 재물을 쌓아가는 실속형 성향입니다.', '크게 승부수를 던지는 투기보다는 꼼꼼한 관리와 절약을 통해 재산을 안정적으로 모아가는 것이 유리합니다. 자신의 예리한 특기나 자격증을 무기로 수익을 창출하며, 사람들과 얽힌 복잡한 동업보다는 단독으로 진행할 수 있는 전문적인 일에서 경제적 보상이 안정적으로 따릅니다.', 70, true),
('day_pillar', '기묘', 'health', '기묘일주 · 건강', '신경이 예민해져 소화기나 간 기능에 무리가 갈 수 있으니 심리적 안정이 필요합니다.', '스트레스를 내면으로 흡수하는 경향이 있어 위염이나 신경성 대장염 등에 노출되기 쉽습니다. 긴장감을 풀어주기 위해 명상, 요가 등의 이완 운동을 꾸준히 하고, 위장에 자극을 주지 않는 부드러운 식습관을 유지하며 긍정적인 마음가짐을 갖는 것이 건강에 큰 도움이 됩니다.', 70, true),
('day_pillar', '경진', 'general', '경진일주 · 총운', '승천하는 용처럼 스케일이 크고 결단력이 뛰어나며 대범한 리더십을 갖춘 기질입니다.', '경금의 강직함과 진토의 거대한 포용력이 결합된 괴강살의 기운으로 만물을 압도하는 카리스마와 배포를 지녔습니다. 자신의 주관이 매우 뚜렷하여 어떤 난관에도 굴복하지 않고 밀어붙이는 불굴의 의지가 돋보입니다. 겉보기에는 차갑고 엄격해 보여도 내면에는 따뜻한 의리가 자리 잡고 있습니다.', 70, true),
('day_pillar', '경진', 'career', '경진일주 · 직업', '강한 추진력과 통솔력을 요하는 군검경, 정치, 대규모 사업 및 토목 분야에 맞습니다.', '평범한 조직원보다는 사람들을 이끌고 큰 프로젝트를 기획하는 리더의 위치에서 진가가 드러납니다. 생살여탈권을 쥐는 직업이나 거대한 자본이 움직이는 건축, 부동산, 권력을 다루는 분야에 인연이 깊으며 독립적으로 일을 개척해 나가는 능력이 탁월합니다.', 70, true),
('day_pillar', '경진', 'love', '경진일주 · 연애', '책임감 있게 헌신하지만 자존심이 세어 연애에서도 주도권을 쥐려 하는 성향입니다.', '가벼운 만남을 꺼리며 진중하고 듬직하게 상대를 보호하려는 태도를 가집니다. 다만 고집이 강하고 다소 무뚝뚝한 면이 있어 상대방이 억압받는다고 느낄 수 있으므로, 내 뜻을 일방적으로 강요하기보다는 상대의 감정을 다정하게 배려하고 양보하는 부드러움이 필수적입니다.', 70, true),
('day_pillar', '경진', 'wealth', '경진일주 · 재물', '스케일이 큰 자산 운용이나 부동산을 통해 거대한 부를 거머쥘 수 있는 대부호의 흐름입니다.', '작은 이익에 연연하지 않고 통 크게 투자하여 큰 수익을 내는 데 재능이 있습니다. 편인의 기운으로 눈치가 빠르고 기회를 포착하는 능력이 뛰어나며, 현금을 융통하기보다는 가치가 높은 문서나 땅에 투자하여 재산을 묵직하게 보존하고 증식하는 것이 경제적 안정을 보장합니다.', 70, true),
('day_pillar', '경진', 'health', '경진일주 · 건강', '과도한 활동으로 피로가 누적되기 쉬우니 위장 등 소화기능과 호흡기 관리에 유의하면 좋습니다.', '강인한 체력을 믿고 무리하게 에너지를 쏟아붓다 보면 한순간에 소화기나 폐 건강에 무리가 올 수 있습니다. 규칙적인 식사와 적절한 휴식 시간을 엄수하고, 탁한 공기를 피해 폐 기능을 강화할 수 있는 맑은 환경에서의 유산소 운동이 장기적인 체력 유지에 이롭습니다.', 70, true),
('day_pillar', '신사', 'general', '신사일주 · 총운', '정교한 보석이 빛을 받는 듯 깔끔하고 세련되며 예의 바른 완벽주의 기질입니다.', '신금의 날카롭고 섬세한 특성과 사화의 밝고 단정한 기운이 만나 매사에 원리원칙을 중시하고 치밀함을 보입니다. 두뇌 회전이 빠르고 직관력이 뛰어나며 겉보기에는 세련되고 다정하지만 속으로는 타인과 선을 긋고 냉정하게 상황을 판단하는 이성적인 면모를 지니고 있습니다.', 70, true),
('day_pillar', '신사', 'career', '신사일주 · 직업', '정확성과 논리력이 요구되는 공직, 법률, 금융, 정밀 기술 및 교육 분야에 적합합니다.', '정관의 바른 기운을 받아 체계적인 조직 생활이나 도덕성이 중시되는 공무원, 법조인 등에서 탁월한 업무 능력을 인정받습니다. 계산이 빠르고 예리하여 회계나 금융업에도 강점이 있으며, 반듯한 이미지로 교육자나 관리직으로서 사람들의 존경을 받기에 충분한 자질을 갖추었습니다.', 70, true),
('day_pillar', '신사', 'love', '신사일주 · 연애', '품위 있고 세련된 연애를 지향하며, 상대에게 헌신적이면서도 이성적인 판단을 유지합니다.', '외모나 분위기가 매력적이라 이성에게 인기가 많으며, 연애 시 예의를 갖추고 다정하게 상대를 배려합니다. 그러나 본인만의 확고한 기준이 있어 상대의 단점이 눈에 띄면 날카롭게 지적하거나 차갑게 돌아설 수 있으므로 상대방을 있는 그대로 수용하는 포용력을 기르는 것이 좋습니다.', 70, true),
('day_pillar', '신사', 'wealth', '신사일주 · 재물', '직장 내 승진이나 탄탄한 조직을 기반으로 명예와 비례하여 안정적으로 재물을 모으는 성향입니다.', '불안정한 투기나 위험한 사업보다는 정당한 노동과 전문 지식을 통한 착실한 수입을 중요하게 생각합니다. 금전 출납이 정확하고 낭비를 싫어하여 알뜰하게 자산을 증식하며, 조직에서 인정받고 지위가 올라갈수록 자연스럽게 상당한 경제적 부가 뒤따르는 흐름을 가집니다.', 70, true),
('day_pillar', '신사', 'health', '신사일주 · 건강', '화기가 금기를 자극하므로 호흡기 계통과 대장 기능 관리에 신경 쓰면 좋습니다.', '스트레스를 받으면 호흡기나 대장 등 건조하고 예민한 기관에 무리가 오기 쉬운 체질입니다. 평소 물을 자주 마셔 체내 수분을 유지하고 기관지를 건조하지 않게 관리하며, 규칙적인 식습관과 명상 등을 통해 마음의 화를 가라앉히는 것이 건강을 유지하는 지름길입니다.', 70, true),
('day_pillar', '임오', 'general', '임오일주 · 총운', '어두운 바다 위를 비추는 달무리처럼 신비롭고 다정하며 적응력이 뛰어난 기질입니다.', '임수의 깊고 넓은 포용력과 오화의 뜨거운 열정이 만나 다정다감하고 사교성이 매우 뛰어난 성향을 띱니다. 겉으로는 부드럽고 융통성이 넘쳐 누구와도 잘 어울리지만, 수화기제의 팽팽한 긴장감으로 인해 내면에는 감정의 기복이 존재하며 매우 빠른 두뇌 회전과 직관력을 감추고 있습니다.', 70, true),
('day_pillar', '임오', 'career', '임오일주 · 직업', '사람들과 교류하며 재물을 다루는 금융, 무역, 유통, 외교 및 언론 분야에 훌륭하게 맞습니다.', '지장간에 재성과 정관을 두루 품어 돈과 명예를 모두 좇는 영리함이 있으며 활동적이고 변화가 많은 환경에서 능력을 발휘합니다. 뛰어난 친화력과 정보력을 무기로 상업, 금융계통이나 사람을 널리 상대하는 외교, 무역 등에서 눈부신 두각을 나타냅니다.', 70, true),
('day_pillar', '임오', 'love', '임오일주 · 연애', '로맨틱하고 부드러운 화술로 이성을 매혹하지만 감정의 변화가 잦은 편입니다.', '매너가 좋고 다정하여 이성에게 인기가 많으며, 연애 분위기를 낭만적으로 이끌어가는 능력이 탁월합니다. 쉽게 사랑에 빠지기도 하고 때로는 감정선이 흔들려 변덕스러운 모습을 보일 수 있으니, 책임감을 가지고 진중하게 관계의 깊이를 더해가는 노력이 필요합니다.', 70, true),
('day_pillar', '임오', 'wealth', '임오일주 · 재물', '돈 냄새를 맡는 감각이 탁월하여 활동력과 인맥을 바탕으로 큰 재물을 운용하는 성향입니다.', '재물 복이 타고나 뛰어난 수완으로 돈을 잘 벌지만, 지출의 씀씀이도 커서 돈이 크게 들어오고 크게 나가는 흐름을 보입니다. 현금을 굴리는 유통업이나 상업에서 능력을 발휘하며, 번 돈을 문서나 부동산 등 묶어두는 자산으로 전환하는 지혜를 발휘하면 안정적인 대부호가 될 수 있습니다.', 70, true),
('day_pillar', '임오', 'health', '임오일주 · 건강', '수와 화의 충돌로 심장과 신장, 비뇨기 계통의 밸런스 유지에 유의하면 좋습니다.', '겉보기엔 활기차지만 체내 온도의 불균형으로 인해 혈압이 불안정해지거나 신장 기능이 저하될 수 있습니다. 과로나 잦은 음주를 피하고 규칙적인 유산소 운동으로 혈액순환을 돕고, 감정 기복을 다스려 심리적 안정을 도모하는 것이 장기적인 건강의 척도입니다.', 70, true),
('day_pillar', '계미', 'general', '계미일주 · 총운', '뜨거운 사막에 내리는 단비처럼 주변을 적시는 희생정신과 끈질긴 인내력을 지닌 기질입니다.', '계수의 맑고 섬세한 성향과 미토의 건조하고 뜨거운 대지가 만나, 극한의 환경에서도 끝까지 살아남는 강인한 생명력을 보여줍니다. 겉으로는 조용하고 다정하며 남을 위해 헌신하는 듯하지만 내면에는 굽히지 않는 강한 고집과 편관 특유의 긴장감이 서려 있는 외유내강형입니다.', 70, true),
('day_pillar', '계미', 'career', '계미일주 · 직업', '타인을 돕고 전문 기술을 발휘하는 교육, 활인(의료, 상담), 기획, 공직 분야에 적합합니다.', '메마른 땅에 물을 대는 형상으로 타인을 위해 희생하고 봉사하는 의료, 복지, 종교 관련 활인업에서 깊은 보람을 느끼고 능률을 올립니다. 예민한 직관과 치밀함을 요구하는 정보 기술이나 연구직, 기획 업무에서도 자신만의 전문성을 확실하게 구축할 수 있습니다.', 70, true),
('day_pillar', '계미', 'love', '계미일주 · 연애', '정 많고 헌신적이나 스트레스를 내면에 쌓아두어 배우자에게 예민하게 굴 수 있습니다.', '연인에게 모성애나 부성애처럼 따뜻하고 세심한 배려를 아끼지 않으며 진지한 관계를 지향합니다. 하지만 마음속에 쌓인 불안감이나 압박감을 제때 풀지 못해 가까운 사람에게 까다롭고 날카롭게 반응할 수 있으니 긍정적인 언어로 자주 소통하며 감정을 교류하는 것이 중요합니다.', 70, true),
('day_pillar', '계미', 'wealth', '계미일주 · 재물', '알뜰한 절약과 전문적인 자격증을 무기로 차곡차곡 재산을 모아가는 실속파의 성향입니다.', '돈을 허투루 낭비하지 않고 치밀하게 계산하여 경제 관념이 대단히 뛰어납니다. 크게 모험을 거는 투자보다는 자신의 뛰어난 전문 기술이나 지식, 자격을 바탕으로 안정적인 수익을 지속적으로 창출해 내며 조용하게 상당한 재력을 구축하는 데 유리한 구조입니다.', 70, true),
('day_pillar', '계미', 'health', '계미일주 · 건강', '수기가 마르기 쉬운 구조이므로 신장, 방광 건강을 챙기고 수분 섭취에 유의하면 좋습니다.', '뜨거운 흙에 수분이 증발하는 형태라 체내에 건조함이 생기고 비뇨기 및 생식기 계통이 약해질 우려가 있습니다. 평소 물을 자주 마시고 수분 대사를 돕는 음식을 섭취하며 신경성 위장 장애나 불면증을 예방하기 위해 취미 생활로 마음의 긴장을 이완시키는 것이 필수적입니다.', 70, true)
